45	/**
46	 * Language adapter for SQL.
47	 */
48	export class SQLLanguageAdapter implements LanguageAdapter {
49	  readonly type = "sql";
50	  readonly defaultCode = `_df = mo.sql(f"""SELECT * FROM """)`;
51	  readonly defaultEngine = DUCKDB_ENGINE;
52	  static fromQuery = (query: string) => `_df = mo.sql(f"""${query.trim()}""")`;
53	
54	  dataframeName = "_df";
55	  lastQuotePrefix: QuotePrefixKind = "f";
56	  lastPythonCode = "";
57	  showOutput = true;
58	  engine = store.get(dataSourceConnectionsAtom).latestEngineSelected;
59	
60	  getDefaultCode(): string {
61	    if (this.engine === this.defaultEngine) {
62	      return this.defaultCode;
63	    }
64	    return `_df = mo.sql(f"""SELECT * FROM """, engine=${this.engine})`;
65	  }
66	
67	  transformIn(
68	    pythonCode: string,
69	  ): [sqlQuery: string, queryStartOffset: number] {
70	    if (!this.isSupported(pythonCode)) {
71	      // Attempt to remove any markdown wrappers
72	      const [transformedCode, offset] =
73	        new MarkdownLanguageAdapter().transformIn(pythonCode);
74	      // Just return the original code
75	      return [transformedCode, offset];
76	    }
77	
78	    this.lastPythonCode = pythonCode;
79	    pythonCode = pythonCode.trim();
80	
81	    // Handle empty strings
82	    if (pythonCode === "") {
83	      this.lastQuotePrefix = "f";
84	      this.showOutput = true;
85	      return ["", 0];
86	    }
87	
88	    const sqlStatement = parseSQLStatement(pythonCode);
89	    if (sqlStatement) {
90	      this.dataframeName = sqlStatement.dfName;
91	      this.showOutput = sqlStatement.output ?? true;
92	      this.engine =
93	        (sqlStatement.engine as ConnectionName) ?? this.defaultEngine;
94	
95	      if (this.engine !== this.defaultEngine) {
96	        // User selected a new engine, set it as latest.
97	        // This makes new SQL statements use the new engine by default.
98	        setLatestEngineSelected(this.engine);
99	      }
100	
101	      return [
102	        dedent(`\n${sqlStatement.sqlString}\n`).trim(),
103	        sqlStatement.startPosition,
104	      ];
105	    }
106	
107	    return [pythonCode, 0];
108	  }
109	
110	  transformOut(code: string): [string, number] {
111	    // Get the quote type from the last transformIn
112	    const prefix = upgradePrefixKind(this.lastQuotePrefix, code);
113	
114	    // Multiline code
115	    // Retrieve any comments that the Python code may have started with
116	    const lines = this.lastPythonCode.split("\n");
117	    const commentLines = [];
118	
119	    for (const line of lines) {
120	      if (line.startsWith("#")) {
121	        commentLines.push(line);
122	      } else {
123	        break;
124	      }
125	    }
126	
127	    const start = `${this.dataframeName} = mo.sql(\n    ${prefix}"""\n`;
128	    const escapedCode = code.replaceAll('"""', String.raw`\"""`);
129	
130	    const showOutputParam = this.showOutput ? "" : ",\n    output=False";
131	    const engineParam =
132	      this.engine === this.defaultEngine ? "" : `,\n    engine=${this.engine}`;
133	    const end = `\n    """${showOutputParam}${engineParam}\n)`;
134	
135	    return [
136	      [...commentLines, start].join("\n") + indentOneTab(escapedCode) + end,
137	      start.length + 1,
138	    ];
139	  }
140	
141	  isSupported(pythonCode: string): boolean {
142	    if (pythonCode.trim() === "") {
143	      return true;
144	    }
145	
146	    // Does not have 2 `mo.sql` calls
147	    if (pythonCode.split("mo.sql").length > 2) {
148	      return false;
149	    }
150	
151	    // Has at least one `mo.sql` call
152	    if (!pythonCode.includes("mo.sql")) {
153	      return false;
154	    }
155	
156	    return parseSQLStatement(pythonCode) !== null;
157	  }
158	
159	  selectEngine(connectionName: ConnectionName): void {
160	    this.engine = connectionName;
161	    setLatestEngineSelected(this.engine);
162	  }
163	
164	  setShowOutput(showOutput: boolean): void {
165	    this.showOutput = showOutput;
166	  }
167	
168	  setDataframeName(dataframeName: string): void {
169	    this.dataframeName = dataframeName;
170	  }
171	
172	  getExtension(
173	    _cellId: CellId,
174	    _completionConfig: CompletionConfig,
175	    _hotkeys: HotkeyProvider,
176	  ): Extension[] {
177	    const keywordCompletion = keywordCompletionSource(StandardSQL);
178	    return [
179	      sql({
