184	              while (match !== null) {
185	                const start = match.index + 1;
186	                const end = pattern.lastIndex - 1;
187	                overlays.push({ from: start, to: end });
188	                match = pattern.exec(text);
189	              }
190	
191	              if (overlays.length === 0) {
192	                return null;
193	              }
194	
195	              return {
196	                parser: pythonLanguage.parser,
197	                overlays,
198	              };
199	            }),
200	          },
201	        ],
202	      }),
