import {
  type Completion,
  type CompletionContext,
  type CompletionResult,
} from "@codemirror/autocomplete";
import type { Extension } from "@codemirror/state";
import { parseMixed, type Parser } from "@lezer/common";
import { tags } from "@lezer/highlight";
import type {
  DelimiterType,
  InlineContext,
  MarkdownConfig,
} from "@lezer/markdown";
import { store } from "@/core/state/jotai";
import { variablesAtom } from "@/core/variables/state";

// Node names for the embedded Python interpolation block.
const PYTHON = "Python";
const PYTHON_MARK = "PythonMark";

// Character codes for the curly braces that delimit an interpolation block.
const OPEN_BRACE = 123; // {
const CLOSE_BRACE = 125; // }

/**
 * Delimiter used to wrap an embedded Python interpolation block.
 * Defined as a constant because it is used in object identity match tests.
 */
const PYTHON_DELIMITER: DelimiterType = {
  mark: PYTHON_MARK,
  resolve: PYTHON,
};

/**
 * Define a Python interpolation parser for Markdown.
 *
 * This recognizes template-style `{ ... }` blocks and parses their contents
 * with the given Python {@link Parser}. Double braces (`{{` / `}}`) are treated
 * as escaped literals and are ignored.
 *
 * @param pythonParser CodeMirror {@link Parser} for Python
 * @param isActivated whether embedded Python parsing is currently enabled
 * @returns Markdown extension
 */
export function parsePython(
  pythonParser: Parser,
  isActivated: () => boolean,
): MarkdownConfig {
  return {
    defineNodes: [
      { name: PYTHON, style: tags.emphasis },
      { name: PYTHON_MARK, style: tags.processingInstruction },
    ],
    parseInline: [
      {
        name: PYTHON,
        parse(cx: InlineContext, next: number, pos: number): number {
          // Only parse when embedded Python is activated.
          if (!isActivated()) {
            return -1;
          }

          // Opening brace of an interpolation block.
          if (next === OPEN_BRACE) {
            // `{{` is an escaped literal brace, not an interpolation.
            if (cx.char(pos + 1) === OPEN_BRACE) {
              return -1;
            }
            return cx.addDelimiter(PYTHON_DELIMITER, pos, pos + 1, true, false);
          }

          // Closing brace of an interpolation block.
          if (next === CLOSE_BRACE) {
            // `}}` is an escaped literal brace, not an interpolation.
            if (cx.char(pos + 1) === CLOSE_BRACE) {
              return -1;
            }
            return cx.addDelimiter(PYTHON_DELIMITER, pos, pos + 1, false, true);
          }

          return -1;
        },
      },
    ],
    wrap: parseMixed((node) => {
      if (node.type.name === PYTHON) {
        // Strip the surrounding braces from the Python overlay.
        const from = node.from + 1;
        const to = node.to - 1;

        // Ensure valid ranges.
        if (from >= to || from < 0 || to < 0) {
          return null;
        }

        return {
          parser: pythonParser,
          overlay: [{ from, to }],
        };
      }

      return null;
    }),
  };
}

/**
 * Build completion options from the current global variables.
 */
function getVariableCompletions(): Completion[] {
  const variables = store.get(variablesAtom);
  return Object.values(variables).map(
    (variable): Completion => ({
      label: variable.name,
      type: "variable",
      detail: variable.dataType ?? undefined,
      boost: 5,
    }),
  );
}

/**
 * Provide variable-name completions for Python embedded inside a Markdown
 * document (via {@link parsePython}). Completions are only surfaced when
 * embedded Python is activated and the completion was explicitly requested.
 *
 * @param isActivated whether embedded Python parsing is currently enabled
 * @returns CodeMirror extension registering the completion source
 */
export function embeddedPythonCompletions(
  isActivated: () => boolean,
): Extension {
  return [
    pythonLanguage.data.of({
      autocomplete: (context: CompletionContext): CompletionResult | null => {
        if (!isActivated()) {
          return null;
        }
        if (!context.explicit) {
          return null;
        }

        const word = context.matchBefore(/\w*/);
        if (!word) {
          return null;
        }

        return {
          from: word.from,
          options: getVariableCompletions(),
          validFor: /^\w*$/,
        };
      },
    }),
  ];
}

/**
 * Completion source for variable names inside a single-brace interpolation
 * block (e.g. `{ variable_name }`). Returns null unless the cursor is inside a
 * valid, unterminated, non-escaped `{ ... }` block.
 */
export function variableCompletionSource(
  context: CompletionContext,
): CompletionResult | null {
  const textBefore = context.state.sliceDoc(0, context.pos);

  const lastOpenBrace = textBefore.lastIndexOf("{");
  // No open brace before the cursor.
  if (lastOpenBrace === -1) {
    return null;
  }

  // A closing brace appears after the last open brace, so the block is
  // already terminated and the cursor is not inside it.
  const lastCloseBrace = textBefore.lastIndexOf("}");
  if (lastCloseBrace > lastOpenBrace) {
    return null;
  }

  // Double-brace escape sequence (`{{`) is a literal brace, not interpolation.
  const isDoubleBrace =
    textBefore[lastOpenBrace - 1] === "{" ||
    textBefore[lastOpenBrace + 1] === "{";
  if (isDoubleBrace) {
    return null;
  }

  const word = context.matchBefore(/\w*/);
  if (!word) {
    return null;
  }

  return {
    from: word.from,
    options: getVariableCompletions(),
    validFor: /^\w*$/,
  };
}
